using System.Text.Json;
using Cortex.Video.Composition;
using Cortex.Video.Editing;
using Xunit;
namespace Cortex.Video.Tests;
public sealed class EditorialDecisionV2Tests {
    [Fact] public async Task V2TransitionAndAudioCompile() {var original=HelengineCompositionTestData.Script();var script=original with{Sources=[..original.Sources,new(){Id="voice",Type=SourceKind.VideoFile,Path="sync-impulse.wav"}]};var basePlan=EditorialDecisionContext.Inherit(script);var plan=basePlan with{Schema=EditingDocumentKinds.DecisionsV2,Catalog=new("helengine.media.capabilities.v1",HelengineCompositionTestData.Catalog().Fingerprint),Scenes=[basePlan.Scenes[0],basePlan.Scenes[1] with{Proposal=basePlan.Scenes[1].Proposal with{Editing=new(){Transition=new(){DurationSec=.5},Audio=[new(){MediaId="voice",StartSec=0,DurationSec=2,SourceInSec=0,Gain=.6,Envelopes=[new(){Type="linear",StartSec=0,DurationSec=.5,From=0,To=1}]}]}}}]};var voice=new MediaSnapshot{Id="voice",SourceId="voice",Path="sync-impulse.wav",Sha256=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes("C:/dev/helworks/builds/helengine/media-composition/fixtures/sync-impulse.wav"))),Type=MediaKind.Audio,Width=0,Height=0,DurationSec=2};var resolved=HelengineCompositionTestData.Resolved(script) with{Media=[HelengineCompositionTestData.Image() with{Sha256=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes("C:/dev/helworks/builds/helengine/media-composition/fixtures/gpu-red.png")))},voice]};var result=HelengineCompositionCompiler.Compile(script,plan,resolved,HelengineCompositionTestData.Catalog());Assert.Single(result.Composition.GetProperty("transitions").EnumerateArray());Assert.Single(result.Composition.GetProperty("audio_clips").EnumerateArray());Assert.Equal(.6,result.Composition.GetProperty("audio_clips")[0].GetProperty("gain").GetDouble());var roundTrip=Assert.IsType<EditorialDecisionPlanDocument>(EditingJson.Parse(EditingJson.Serialize(plan)));Assert.Equal(EditingDocumentKinds.DecisionsV2,roundTrip.Schema);Cortex.Core.Flows.FlowDomain.Check(EditorialDecisionFlowTypes.ExecutionProjection(plan),EditorialDecisionFlowTypes.ForCapabilities(HelengineCompositionTestData.Catalog()));var client=new HelengineCompositionClient("C:/dev/helworks/builds/helengine/media-composition/worktrees/helengine/engine/helengine.vfx.cli/bin/Debug/net9.0/helengine.vfx.cli.dll");await client.ValidateAsync(result.Composition,"C:/dev/helworks/builds/helengine/media-composition/fixtures",CancellationToken.None);}
    [Fact] public void HumanOverrideSurvivesCatalogRefresh() {var script=HelengineCompositionTestData.Script();var initial=EditorialDecisionContext.Inherit(script);var plan=initial with{Schema=EditingDocumentKinds.DecisionsV2,Catalog=new("helengine.media.capabilities.v1",HelengineCompositionTestData.Catalog().Fingerprint)};var changed=EditorialDecisionMerge.ApplyPatch(plan,"a",[new("motion.to_scale",JsonSerializer.SerializeToElement(1.7))],1);var refreshed=EditorialDecisionMerge.Replan(changed,plan with{Catalog=new("helengine.media.capabilities.v1",new string('f',64))},script);Assert.Equal(1.7,EditorialDecisionMerge.Effective(refreshed).Scenes[0].Proposal.Motion.ToScale);Assert.Single(refreshed.Scenes[0].Overrides);}
}
